<?php require __DIR__.'/../includes/app.php';need('System Administrator','Business Manager');head('Business reports');
$m=q("SELECT DATE_FORMAT(payment_date,'%Y-%m') m,SUM(amount) a FROM payments WHERE status IN('completed','partially_refunded') GROUP BY m ORDER BY m DESC LIMIT 12")->fetchAll();$m=array_reverse($m);
$k=['Collected revenue'=>q("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status IN('completed','partially_refunded')")->fetchColumn(),'Refunds processed'=>q("SELECT COALESCE(SUM(amount),0) FROM payment_refunds WHERE status='processed'")->fetchColumn(),'Outstanding'=>q("SELECT COALESCE(SUM(outstanding_balance),0) FROM vw_invoice_balances WHERE status NOT IN('void','draft')")->fetchColumn(),'Deposits held'=>q("SELECT COALESCE(SUM(IF(transaction_type='received',amount,-amount)),0) FROM deposit_transactions WHERE status='completed' AND transaction_type<>'adjustment'")->fetchColumn(),'Maintenance cost'=>q("SELECT COALESCE(SUM(cost),0) FROM maintenance_records WHERE status<>'cancelled'")->fetchColumn()];
echo '<div class="row g-3 mb-4">';foreach($k as $l=>$v)echo '<div class="col-6 col-xl"><div class="card kpi p-3"><div class="text-muted small">'.$l.'</div><div class="v">'.money($v).'</div></div></div>';echo '</div>';?>
<div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-header">Monthly revenue</div><div class="card-body"><canvas id="ch" height="130"></canvas></div></div></div>
<div class="col-lg-5"><div class="card"><div class="card-header">Fleet status</div><div class="card-body table-responsive p-0"><table class="table table-sm table-hover mb-0"><tbody><?php foreach(q('SELECT status,COUNT(*) n FROM vehicles GROUP BY status')->fetchAll() as $x)echo '<tr><td>'.badge($x['status']).'</td><td class="text-end">'.(int)$x['n'].'</td></tr>';?></tbody></table></div></div></div>
<div class="col-lg-6"><div class="card"><div class="card-header">Top vehicles by revenue</div><div class="card-body table-responsive p-0"><table class="table table-sm table-hover"><thead><tr><th scope="col">Vehicle</th><th scope="col">Rentals</th><th scope="col" class="text-end">Billed</th></tr></thead><tbody><?php foreach(q("SELECT v.registration_no,v.make,v.model,COUNT(*) n,SUM(r.final_amount) s FROM rentals r JOIN vehicles v USING(vehicle_id) GROUP BY v.vehicle_id ORDER BY s DESC LIMIT 5")->fetchAll() as $x)echo '<tr><td>'.e($x['make'].' '.$x['model'].' · '.$x['registration_no']).'</td><td>'.(int)$x['n'].'</td><td class="text-end">'.money($x['s']).'</td></tr>';?></tbody></table></div></div></div>
<div class="col-lg-6"><div class="card"><div class="card-header">Reservations by status</div><div class="card-body table-responsive p-0"><table class="table table-sm table-hover"><tbody><?php foreach(q('SELECT status,COUNT(*) n FROM reservations GROUP BY status')->fetchAll() as $x)echo '<tr><td>'.badge($x['status']).'</td><td class="text-end">'.(int)$x['n'].'</td></tr>';?></tbody></table></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.3/dist/chart.umd.min.js"></script><script>new Chart(ch,{type:'bar',data:{labels:<?=json_encode(array_column($m,'m'))?>,datasets:[{label:'RWF',data:<?=json_encode(array_map('floatval',array_column($m,'a')))?>,backgroundColor:'rgba(201, 99, 53, .82)',hoverBackgroundColor:'#a94d26',borderRadius:7}]},options:{plugins:{legend:{display:false}},scales:{x:{grid:{display:false}},y:{beginAtZero:true,grid:{color:'rgba(22, 52, 61, .07)'}}}}})</script><?php foot();
